('ResultDelivered', 'تسليم النتيجة', 'تم تسليم نتيجتك عبر القناة المحددة. يُرجى مراجعة حسابك إذا احتجت إلى نسخة آمنة.'),
('STAFF_CREATED', 'حساب موظف جديد', 'أُنشئ حساب موظف جديد. يُرجى التحقق من الدور والصلاحيات الممنوحة.'),
('STAFF_DEACTIVATED', 'تعطيل حساب موظف', 'عُطّل حساب موظف. يُرجى مراجعة أثر ذلك في المهام والصلاحيات.'),
('STAFF_UPDATED', 'تحديث حساب موظف', 'تغيّرت بيانات حساب موظف. يُرجى مراجعة التعديل والصلاحيات المرتبطة.'),
('STUDY_EXPORTED', 'تصدير دراسة طبية', 'صُدّرت دراسة طبية من PACS. يُرجى مراجعة سجل الوصول ومبرر التصدير.'),
('STUDY_IMPORTED', 'استيراد دراسة طبية', 'استُوردت دراسة طبية إلى PACS. يُرجى التحقق من ربطها الصحيح.'),
('SUPPLY_ADDED_PAYMENT_DUE', 'مستلزم أضيف للفاتورة', 'أُضيف مستلزم إلى فاتورة قائمة ونشأ مبلغ مستحق. يُرجى مراجعة الفاتورة.'),
('TOKEN_REUSE_DETECTED', 'تنبيه أمني بشأن جلسة الدخول', 'رُصد استخدام مكرر لرمز دخول وأُلغيت الجلسات المتأثرة. يُرجى مراجعة أمان الحساب فورًا.')
)
UPDATE notification_templates AS template
SET subject = CASE WHEN template.channel IN ('InApp', 'Email') THEN copy.subject_ar ELSE NULL END,
    body = copy.body_ar,
    updated_at = CURRENT_TIMESTAMP
FROM copy
WHERE template.event_type = copy.event_type
  AND template.language = 'ar'
  AND template.created_by IS NULL
  AND template.body LIKE 'تم تسجيل % في نظام VIARA.%';
